// 2 Preparar Download do Áudio
// O nó 1 (receiver) já entrega o link do arquivo de voz em msg.payload.weblink.
// As chaves ficam nas variáveis de ambiente da aba (duplo clique na aba > Environment).
msg.groqKey = env.get("GROQ_API_KEY");
msg.telegramContext = msg.payload || {};
msg.chatId = msg.payload ? msg.payload.chatId : null;
msg.veioDeAudio = true;          // quem fala por áudio recebe a resposta em áudio (nó 7)
msg.canal = "telegram";

if (!msg.payload || !msg.payload.weblink) {
    node.error("Áudio sem link de download.", msg);
    return null;
}
msg.url = msg.payload.weblink;   // o próximo nó baixa o arquivo .ogg (binário)
return msg;

// 2.1 Montar Form: monta o pedido multipart para o Whisper (Groq) transcrever o áudio.
const audioBuffer = msg.payload;
if (!Buffer.isBuffer(audioBuffer) || audioBuffer.length === 0) {
    node.error("Download do áudio falhou.", msg);
    return null;
}
const boundary = '----NodeREDFormBoundary' + Math.random().toString(16).substr(2);

let body = [];
// parte 1: o arquivo de áudio
body.push(Buffer.from('--' + boundary + '\r\n'));
body.push(Buffer.from('Content-Disposition: form-data; name="file"; filename="audio.ogg"\r\n'));
body.push(Buffer.from('Content-Type: audio/ogg\r\n\r\n'));
body.push(audioBuffer);
body.push(Buffer.from('\r\n'));
// parte 2: o modelo de transcrição
body.push(Buffer.from('--' + boundary + '\r\n'));
body.push(Buffer.from('Content-Disposition: form-data; name="model"\r\n\r\n'));
body.push(Buffer.from('whisper-large-v3\r\n'));
// parte 3: o idioma (português)
body.push(Buffer.from('--' + boundary + '\r\n'));
body.push(Buffer.from('Content-Disposition: form-data; name="language"\r\n\r\n'));
body.push(Buffer.from('pt\r\n'));
body.push(Buffer.from('--' + boundary + '--\r\n'));

msg.headers = {
    'Authorization': 'Bearer ' + msg.groqKey,
    'Content-Type': 'multipart/form-data; boundary=' + boundary
};
msg.url = 'https://api.groq.com/openai/v1/audio/transcriptions';
msg.payload = Buffer.concat(body);
return msg;

// 2.2 Converter Transcrição p/ Entrada
// Saída 1 -> nó 3 (entendimento) | Saída 2 -> Telegram ("Você disse: ...")
const texto = (msg.payload && msg.payload.text) ? String(msg.payload.text).trim() : "";
const chatId = msg.chatId;

if (!texto) {
    const aviso = { payload: { chatId: chatId, type: "message",
        content: "Não consegui entender o áudio. Pode repetir ou escrever sua mensagem?" } };
    return [null, aviso];
}

// Devolve ao formato de mensagem de texto do Telegram, como se a pessoa tivesse digitado.
msg.payload = msg.telegramContext || {};
msg.payload.type = "message";
msg.payload.content = texto;

// Mostra o que foi entendido (ajuda a pessoa e a demonstração no vídeo).
const eco = { payload: { chatId: chatId, type: "message", content: "🎤 Você disse: \"" + texto + "\"" } };
return [msg, eco];

// 3 Montar Prompt IA - Intenções e Entidades
// Saída 1 -> Groq (IA) | Saída 2 -> nó 4 direto (mensagens que não precisam de IA)
const GROQ_API_KEY = env.get("GROQ_API_KEY");

const rawText = (msg.payload && msg.payload.content) ? String(msg.payload.content).trim() : "";
const textLower = rawText.toLowerCase();

msg.telegramContext = msg.payload || {};

// Comandos, respostas de uma palavra e códigos de rastreio não precisam da IA
// (economiza chamadas). O nó 4 trata essas mensagens diretamente.
const SEM_IA = ["/start", "/help", "/ajuda", "/audio", "/texto", "inicio", "início", "reiniciar",
    "oi", "olá", "ola", "manhã", "manha", "tarde", "noite"];
const soCodigo = /^sd\s?-?\d{4,5}$/.test(textLower);
if (!rawText || SEM_IA.includes(textLower) || soCodigo) {
    msg.ai = {};
    return [null, msg];
}

// INTENÇÕES (5 principais, cada uma com 12 exemplos) E ENTIDADES (5, com sinônimos).
// A IA só classifica e extrai. Os dados (status, drones, bateria) vêm SEMPRE do banco (nós 4, 5 e 6).
const instrucoes =
    "Você é o módulo de entendimento do Assistente SADEC (Sistema Autônomo de Drones de Entrega e Cuidado): uma rede de drones que transporta " +
    "órgãos para transplante, remédios e ajuda em emergências, sustentada por entregas comerciais. " +
    "Analise a mensagem do cidadão e responda SOMENTE com um JSON.\n\n" +

    "Campo 'intencao' (uma destas):\n" +
    "- 'rastrear_entrega': quer saber onde está a entrega. Ex.: 'Onde está minha entrega?', 'Quero rastrear meu pedido', " +
    "'Meu remédio já saiu?', 'Quanto tempo falta para o drone chegar?', 'O drone já decolou?', 'Status da minha entrega', " +
    "'Cadê meu pedido?', 'Minha encomenda está a caminho?', 'Quero acompanhar o drone em tempo real', " +
    "'A entrega vai demorar muito?', 'Previsão de chegada do pedido SD1001', 'Rastrear SD1004'.\n" +

    "- 'pedir_remedio': quer receber remédio de uso contínuo em casa. Ex.: 'Preciso receber meu remédio em casa', " +
    "'Quero pedir meus medicamentos', 'Minha mãe não consegue ir à farmácia buscar o remédio', 'Pedir remédio de uso contínuo', " +
    "'Quero que o drone traga minha insulina', 'A UBS fica longe, dá pra mandar o remédio?', 'Solicitar entrega de medicamento', " +
    "'Acabou meu remédio de pressão', 'Sou idoso e preciso dos meus remédios em casa', " +
    "'Tenho dificuldade de locomoção e preciso de remédio', 'Pode entregar remédio na zona rural?', 'Quero remédio no Itaquera'.\n" +

    "- 'solicitar_transporte_urgente': órgão para transplante ou emergência. Ex.: 'Preciso de um transporte urgente', " +
    "'É uma emergência', 'Precisamos transportar um órgão para transplante', 'Temos um rim que precisa chegar ao InCor', " +
    "'A enchente isolou meu bairro e precisamos de água', 'Socorro, estamos ilhados', " +
    "'A estrada caiu e ninguém consegue trazer remédio', 'Preciso de kit de primeiros socorros agora', " +
    "'A Defesa Civil precisa enviar mantimentos', 'Houve um deslizamento e precisamos de ajuda', " +
    "'O coração para transplante precisa sair agora para o HC', 'Chamado de emergência no Parelheiros'.\n" +

    "- 'reagendar_entrega': quer mudar o horário da entrega. Ex.: 'Quero reagendar minha entrega', " +
    "'Posso mudar o horário da entrega?', 'Não vou estar em casa, dá para entregar em outro horário?', 'Trocar o horário do pedido', " +
    "'Remarcar entrega', 'Prefiro receber à tarde', 'Pode entregar amanhã de manhã?', 'Adiar a entrega', " +
    "'Mudar o período de entrega', 'Quero receber em outro período', 'Não posso receber agora', 'Reagendar o SD1002 para a noite'.\n" +

    "- 'reportar_problema': reclamação ou aviso de problema. Ex.: 'Quero fazer uma reclamação', 'Tem um drone caído aqui na rua', " +
    "'O remédio chegou danificado', 'A entrega veio errada', 'O drone pousou no lugar errado', " +
    "'O drone está fazendo um barulho estranho', 'Meu pedido atrasou demais', 'Ninguém me avisou que a entrega mudou', " +
    "'A caixa chegou aberta', 'Vi um drone com a luz de alerta piscando', 'O drone quase bateu em um fio', 'Estou insatisfeito com o serviço'.\n" +

    "- 'saudacao': cumprimentos. Ex.: 'Oi', 'Bom dia', 'Olá, tudo bem?'.\n" +
    "- 'ajuda': pergunta o que o bot faz. Ex.: 'O que você faz?', 'Como funciona?', 'Me ajuda'.\n" +
    "- 'despedida': encerra. Ex.: 'Tchau', 'Obrigado, era só isso', 'Valeu'.\n" +
    "- 'desconhecido': outro assunto, ou mensagem que só traz um dado solto (ex.: 'Capão Redondo', 'InCor', 'à tarde', 'responda em áudio').\n\n" +

    "Entidades (use exatamente os valores entre aspas simples, ou null se não aparecer):\n" +
    "- 'tipo_carga': 'orgao' (órgão, rim, fígado, coração, córnea, pulmão, tecido, transplante), " +
    "'remedio' (remédio, medicamento, medicação, insulina, comprimido), " +
    "'kit_emergencia' (kit de primeiros socorros, água, mantimentos, kit), " +
    "'exame' (amostra, exame de sangue, material de exame, insumo, vacina), " +
    "'encomenda' (pacote, compra, pedido do iFood, lanche, Shopee, AliExpress).\n" +
    "- 'prioridade': 'nivel_1_orgaos' (prioridade máxima, transplante urgente), " +
    "'nivel_2_emergencia' (emergência, enchente, deslizamento, ilhados, Defesa Civil), " +
    "'nivel_3_saude' (saúde, uso contínuo, remédio mensal, UBS), 'nivel_4_comercial' (comercial, delivery, sem pressa).\n" +
    "- 'bairro': 'Capão Redondo' (Capão, Capao), 'Jardim Ângela' (Jardim Angela, Jd Ângela), 'Brasilândia' (Brasilandia, Vila Brasilândia), " +
    "'Paraisópolis' (Paraisopolis), 'Itaquera' (Cohab Itaquera), 'Parelheiros' (zona rural de Parelheiros), " +
    "'Centro' (Sé, República, centro da cidade), 'Mooca' (Moóca).\n" +
    "- 'hospital': 'Hospital das Clínicas' (HC, Clínicas), 'InCor' (Instituto do Coração), 'Santa Casa' (Santa Casa de São Paulo), " +
    "'Hospital São Paulo' (HSP, hospital da Unifesp), 'Hospital do Servidor Público' (Hospital do Servidor, HSPE).\n" +
    "- 'horario': 'manha' (manhã, de manhã, cedo, pela manhã), 'tarde' (à tarde, de tarde, depois do almoço), " +
    "'noite' (à noite, de noite, depois das 18h).\n" +
    "- 'formato': 'audio' se a pessoa pedir respostas em áudio ou voz; 'texto' se pedir respostas escritas.\n\n" +

    "Responda estritamente no formato JSON: {\"intencao\": \"...\", \"tipo_carga\": null, \"prioridade\": null, " +
    "\"bairro\": null, \"hospital\": null, \"horario\": null, \"formato\": null}";

msg.headers = {
    'Authorization': 'Bearer ' + GROQ_API_KEY,
    'Content-Type': 'application/json'
};
msg.url = 'https://api.groq.com/openai/v1/chat/completions';
msg.payload = {
    model: "openai/gpt-oss-120b",
    temperature: 0,
    response_format: { type: "json_object" },
    messages: [
        { role: "system", content: instrucoes },
        { role: "user", content: rawText }
    ]
};
return [msg, null];

// 3.1 Processar JSON IA: lê a resposta da IA e devolve a mensagem original junto com o resultado.
let aiResult = { intencao: "desconhecido" };

try {
    if (msg.payload && msg.payload.choices && msg.payload.choices[0] && msg.payload.choices[0].message) {
        aiResult = JSON.parse(msg.payload.choices[0].message.content);
    } else {
        node.warn("A IA não respondeu (confira a chave do Groq). Seguindo como 'desconhecido'.");
    }
} catch (e) {
    node.warn("Erro ao interpretar JSON da IA, mantendo comportamento padrão.");
}

msg.payload = msg.telegramContext || {};
msg.ai = aiResult;
return msg;

// 4 Analisar Pedido: decide o que fazer com a intenção e as entidades.
// Rastreio e pedido de remédio usam o núcleo comum da API (global sadecApi): o mesmo banco, os mesmos códigos
// SD e a mesma decisão da Central Java usados pelo site. O chatbot não escolhe drone por conta própria.
const api = global.get("sadecApi");
const NOME_STATUS = { aguardando: "na fila", atribuida: "com drone reservado, aguardando decolagem", em_voo: "em voo monitorado",
    entregue: "entregue", reagendada: "reagendada", outro_meio: "encaminhada a outro meio de transporte", aguardando_resgate: "aguardando resgate após pouso seguro" };
// Saída 1 -> 5 BD Consulta (leitura) | Saída 2 -> 5.1 BD Gravação | Saída 3 -> 7 resposta direta
if (!msg.payload || !msg.payload.chatId) return [null, null, null];

const chatId = msg.payload.chatId;
const rawText = msg.payload.content ? String(msg.payload.content).trim() : "";
const textLower = rawText.toLowerCase();

// ---------- Valores aceitos (os mesmos do prompt do nó 3) ----------
const INTENCOES = ["rastrear_entrega", "pedir_remedio", "solicitar_transporte_urgente", "reagendar_entrega",
    "reportar_problema", "saudacao", "ajuda", "despedida", "desconhecido"];
const TIPOS_CARGA = ["orgao", "remedio", "kit_emergencia", "exame", "encomenda"];
const PRIORIDADES = ["nivel_1_orgaos", "nivel_2_emergencia", "nivel_3_saude", "nivel_4_comercial"];
const BAIRROS = ["Capão Redondo", "Jardim Ângela", "Brasilândia", "Paraisópolis", "Itaquera", "Parelheiros", "Centro", "Mooca"];
const HOSPITAIS = ["Hospital das Clínicas", "InCor", "Santa Casa", "Hospital São Paulo", "Hospital do Servidor Público"];
const HORARIOS = ["manha", "tarde", "noite"];
const NOME_HORARIO = { manha: "manhã", tarde: "tarde", noite: "noite" };

const mensagemBoasVindas = "Olá! 👋 Eu sou o Assistente SADEC, do Sistema Autônomo de Drones de Entrega e Cuidado: a rede de drones que leva órgãos, " +
    "remédios e ajuda em emergências para quem mais precisa.\n\n" +
    "Posso:\n• rastrear sua entrega\n• pedir seu remédio de uso contínuo\n• solicitar transporte urgente\n" +
    "• reagendar uma entrega\n• registrar um problema\n\n" +
    "Você pode escrever ou mandar áudio. Para ouvir as respostas em áudio, diga \"responda em áudio\" (ou /audio).";
const mensagemAjuda = "Exemplos do que você pode dizer:\n• \"Onde está a entrega SD1001?\"\n• \"Quero pedir meu remédio no Capão Redondo\"\n" +
    "• \"Precisamos levar um rim para o InCor\"\n• \"Reagendar o SD1002 para a noite\"\n• \"Tem um drone caído na minha rua\"";
const mensagemNaoEntendi = "Desculpe, não entendi. Posso rastrear uma entrega, pedir remédio, solicitar transporte urgente, " +
    "reagendar uma entrega ou registrar um problema. Diga /ajuda para ver exemplos.";

// Só aceita valores da lista (protege o banco de qualquer texto inesperado vindo da IA)
function valor(v, lista) {
    if (v === null || v === undefined) return null;
    const s = String(v).trim();
    return lista.includes(s) ? s : null;
}

// Para gravar texto livre no banco: dobra as aspas simples (evita quebrar o SQL).
function seguro(t) {
    return String(t).replace(/'/g, "''");
}

function responder(texto) {
    msg.payload.type = "message";
    msg.payload.content = texto;
    return [null, null, msg];
}

// ---------- Memória da conversa (variáveis de contexto por chat) ----------
// memoria_  = dados já informados: bairro, hospital, tipo de urgência, horário e último código
// espera_   = o que o bot perguntou por último (bairro, hospital, codigo, horario)
// pendente_ = intenção que estava sendo atendida quando o bot perguntou algo
// formato_  = "texto" ou "audio": como a pessoa quer receber as respostas (usado no nó 7)
let memoria = flow.get("memoria_" + chatId) || {};
const espera = flow.get("espera_" + chatId) || null;
const pendente = flow.get("pendente_" + chatId) || null;

function salvarMemoria() {
    flow.set("memoria_" + chatId, memoria);
}
function limparEspera() {
    flow.set("espera_" + chatId, null);
    flow.set("pendente_" + chatId, null);
}
function perguntar(oQue, intencaoAtual, texto) {
    salvarMemoria();
    flow.set("espera_" + chatId, oQue);
    flow.set("pendente_" + chatId, intencaoAtual);
    return responder(texto);
}
function limparConversa() {
    memoria = {};
    salvarMemoria();
    limparEspera();
}

// Leitura no banco: o SQL vai em msg.topic e os valores em msg.payload (lista, na ordem dos $).
function consultarBanco(acao, sql, valores) {
    msg.acao = acao;
    msg.topic = sql;
    msg.telegramContext = msg.payload;
    msg.payload = valores;
    return [msg, null, null];
}
// Gravação no banco (INSERT/UPDATE): o SQL vai em msg.topic.
function gravarBanco(acao, sql) {
    msg.acao = acao;
    msg.topic = sql;
    msg.telegramContext = msg.payload;
    return [null, msg, null];
}


if (["/start", "inicio", "início", "reiniciar"].includes(textLower)) {
    limparConversa();
    return responder(mensagemBoasVindas);
}

// ---------- Resultado da IA (nó 3) + atalhos sem IA ----------
const ai = msg.ai || {};
let intencao = valor(ai.intencao, INTENCOES) || "desconhecido";
let novoFormato = valor(ai.formato, ["audio", "texto"]);

if (["oi", "olá", "ola"].includes(textLower)) intencao = "saudacao";
if (["/help", "/ajuda"].includes(textLower)) intencao = "ajuda";
if (textLower === "/audio") novoFormato = "audio";
if (textLower === "/texto") novoFormato = "texto";

const novo = {
    tipo_carga: valor(ai.tipo_carga, TIPOS_CARGA),
    prioridade: valor(ai.prioridade, PRIORIDADES),
    bairro: valor(ai.bairro, BAIRROS),
    hospital: valor(ai.hospital, HOSPITAIS),
    horario: valor(ai.horario, HORARIOS)
};
// Respostas de uma palavra que pularam a IA
if (textLower === "manhã" || textLower === "manha") novo.horario = "manha";
if (textLower === "tarde" || textLower === "noite") novo.horario = textLower;

// O código de rastreio é lido direto do texto (padrão SD + 4 ou 5 números), sem IA.
const achou = rawText.toUpperCase().match(/SD\s?-?(\d{4,5})/);
const codigo = achou ? "SD" + achou[1] : null;

const trouxeDado = codigo || Object.keys(novo).some(function (k) { return novo[k]; });

// ---------- Variável de contexto: resposta em áudio ou em texto ----------
if (novoFormato) {
    flow.set("formato_" + chatId, novoFormato);
    if (["desconhecido", "saudacao", "ajuda"].includes(intencao)) {
        return responder(novoFormato === "audio"
            ? "Combinado! A partir de agora respondo em áudio. Para voltar ao texto, diga \"responda em texto\" (ou /texto)."
            : "Combinado! A partir de agora respondo em texto.");
    }
}

// Resposta curta a uma pergunta do bot (ex.: "Itaquera" depois de "Em qual bairro?"):
// a intenção é a que estava pendente.
if (intencao === "desconhecido" && trouxeDado && espera && pendente) {
    intencao = pendente;
}
// Só o código, sem pergunta pendente (ex.: "SD1004"): entende como rastreio.
if (intencao === "desconhecido" && codigo && !espera) {
    intencao = "rastrear_entrega";
}
const continuacao = (intencao === pendente);

// ---------- Saudação, ajuda e despedida ----------
if (intencao === "saudacao") {
    limparEspera();
    return responder("Olá! Em que posso ajudar? Posso rastrear, pedir remédio, solicitar transporte urgente, reagendar ou registrar um problema.");
}
if (intencao === "ajuda") {
    return responder(mensagemAjuda);
}
if (intencao === "despedida") {
    limparConversa();
    return responder("Por nada! O SADEC está sempre por aqui. Até mais!");
}

// ---------- 1) Rastrear entrega ----------
if (intencao === "rastrear_entrega") {
    const cod = codigo || memoria.ultimo_codigo;
    if (!cod) {
        return perguntar("codigo", intencao, "Qual é o código de rastreio? Ele começa com SD, por exemplo SD1001.");
    }
    memoria.ultimo_codigo = cod;
    salvarMemoria();
    limparEspera();
    try {
        const p = api.obterPedido(cod);
        let t = "📦 Entrega " + p.codigo + " (P" + p.prioridade + ", " + p.tipo_carga + " para " + p.destino + "): " + (NOME_STATUS[p.status] || p.status) + ".";
        if (p.drone_codigo) t += " Drone: " + p.drone_codigo + ".";
        if (p.motivo) t += " Motivo: " + p.motivo;
        if (p.recebimento) t += " Recebido por " + p.recebimento.destinatario + " (" + p.recebimento.estado_carga + ").";
        if (p.eventos && p.eventos.length) t += "\nÚltimo evento: " + p.eventos[p.eventos.length - 1].descricao;
        return responder(t);
    } catch (e) {
        return responder(e.status === 404 ? "Não encontrei a entrega " + cod + ". Confira o código (ex.: SD1001)." : "Não consegui consultar agora. Tente de novo em instantes.");
    }
}

// ---------- 2) Pedir remédio (modo Saúde, nível 3) ----------
if (intencao === "pedir_remedio") {
    // VARIÁVEL DE CONTEXTO: se a pessoa já disse o bairro antes, o bot lembra.
    const bairro = novo.bairro || memoria.bairro;
    if (!bairro) {
        return perguntar("bairro", intencao, "Claro! A entrega de remédios de uso contínuo tem prioridade nível 3 (Saúde). " +
            "Em qual bairro você mora? Atendemos: " + BAIRROS.join(", ") + ".");
    }
    const periodo = novo.horario || "manha";
    memoria.bairro = bairro;
    salvarMemoria();
    limparEspera();
    try {
        const r = api.criarPedido({ tipo_carga: "remedio", destino: bairro, periodo: periodo, canal: "chatbot", chat: String(chatId),
            solicitante: { tipo: "cidadao", nome: "Chatbot (" + (msg.canal || "web") + ")" } });
        memoria.ultimo_codigo = r.pedido.codigo;
        salvarMemoria();
        let t = "💊 Pedido de remédio registrado!\nCódigo: " + r.pedido.codigo + "\nBairro: " + bairro + "\nPrioridade: nível 3 (Saúde)";
        t += r.pedido.drone_codigo ? "\nDrone reservado: " + r.pedido.drone_codigo + " (decola após confirmação da Central)." : "\nSituação: " + (NOME_STATUS[r.pedido.status] || r.pedido.status) + ".";
        if (!novo.bairro) t += "\n(Usei o bairro que você informou antes.)";
        return responder(t + "\nSimulação acadêmica: nenhum remédio real é enviado.");
    } catch (e) {
        return responder("Não consegui registrar o pedido agora (" + (e.status ? e.message : "erro interno") + ").");
    }
}

// ---------- 3) Transporte urgente: órgão (nível 1) ou emergência (nível 2) ----------
if (intencao === "solicitar_transporte_urgente") {
    let tipo = null;
    if (novo.tipo_carga === "orgao" || novo.prioridade === "nivel_1_orgaos") tipo = "orgao";
    else if (novo.tipo_carga || novo.prioridade) tipo = "emergencia";
    else if (continuacao && memoria.tipo_urgente) tipo = memoria.tipo_urgente;
    else tipo = novo.hospital ? "orgao" : "emergencia";
    memoria.tipo_urgente = tipo;

    let destino, fator, prioridade, carga;
    if (tipo === "orgao") {
        destino = novo.hospital || (continuacao ? memoria.hospital : null);
        if (!destino) {
            return perguntar("hospital", intencao, "Transporte de órgão tem prioridade máxima (nível 1) e é pedido por hospitais " +
                "e pela Central Estadual de Transplantes. Qual é o hospital de destino? Atendemos: " + HOSPITAIS.join(", ") + ".");
        }
        memoria.hospital = destino;
        fator = 1.3;          // REGRA: para órgãos, a bateria precisa cobrir a rota com 30% de folga
        prioridade = 1;
        carga = "orgao";
    } else {
        destino = novo.bairro || memoria.bairro;
        if (!destino) {
            return perguntar("bairro", intencao, "Entendi, é uma emergência (nível 2). Se houver risco de vida, ligue também " +
                "para a Defesa Civil (199) ou o SAMU (192). Em qual bairro você está?");
        }
        memoria.bairro = destino;
        fator = 1.0;
        prioridade = 2;
        carga = "kit_emergencia";
    }
    salvarMemoria();
    limparEspera();
    // REGRA DE AUTORIZAÇÃO: o chatbot público não despacha P1 nem P2. O pedido é feito pela unidade autorizada
    // (hospital / Central de Transplantes para órgãos; Defesa Civil / município para emergências) na Central SADEC,
    // onde a Central Java decide o drone. Aqui só orientamos (sem gravar nem escolher drone).
    return responder((prioridade === 1
        ? "🫀 Transporte de órgão (nível 1) para " + destino + ": o pedido precisa vir do hospital ou da Central de Transplantes, " +
          "pelo canal autorizado da Central SADEC. Assim que for registrado, a Central reserva o drone com 30% de reserva de bateria."
        : "🚨 Emergência (nível 2) em " + destino + ": a solicitação é feita pela Defesa Civil ou pelo município na Central SADEC. " +
          "Se houver risco de vida, ligue agora para o SAMU (192) ou a Defesa Civil (199).") +
        "\nO chatbot público não autoriza despacho de prioridade 1 ou 2.");
}

// ---------- 4) Reagendar entrega ----------
if (intencao === "reagendar_entrega") {
    if (novo.horario) memoria.horario = novo.horario;
    const horario = novo.horario || (continuacao ? memoria.horario : null);
    const cod = codigo || memoria.ultimo_codigo;
    if (!cod) {
        return perguntar("codigo", intencao, "Qual é o código da entrega que você quer reagendar? Ex.: SD1002.");
    }
    memoria.ultimo_codigo = cod;
    if (!horario) {
        return perguntar("horario", intencao, "Para qual período você quer reagendar a entrega " + cod + ": manhã, tarde ou noite?");
    }
    delete memoria.horario;
    salvarMemoria();
    limparEspera();
    msg.dados = { codigo: cod, horario: horario };
    // Primeiro confere o status: só dá para reagendar o que ainda não decolou (ver nó 6).
    return consultarBanco("conferir_reagendamento",
        "SELECT CD_Rastreio, ST_Status, NR_Prioridade FROM tbl_entrega WHERE CD_Rastreio = $codigo", [cod]);
}

// ---------- 5) Reportar problema ----------
if (intencao === "reportar_problema") {
    const cod = codigo || memoria.ultimo_codigo || null;
    limparEspera();
    msg.dados = { codigo: cod };
    return gravarBanco("ocorrencia_registrada",
        "INSERT INTO tbl_ocorrencia (NR_Chat, CD_Rastreio, DS_Relato, DT_Registro) VALUES ('" + seguro(chatId) + "', " +
        (cod ? "'" + cod + "'" : "NULL") + ", '" + seguro(rawText.substring(0, 500)) + "', datetime('now', 'localtime'))");
}

// ---------- Não entendeu ----------
// Se o bot estava esperando uma resposta, explica o que é aceito (como um "anything_else").
if (espera === "bairro") return responder("Não reconheci o bairro. Atendemos: " + BAIRROS.join(", ") + ".");
if (espera === "hospital") return responder("Não encontrei esse hospital na rede piloto. Atendemos: " + HOSPITAIS.join(", ") +
    ". Para outros hospitais, a Central de Transplantes deve acionar helicóptero ou ambulância.");
if (espera === "codigo") return responder("Não encontrei um código válido. Ele começa com SD e tem números, por exemplo SD1001.");
if (espera === "horario") return responder("Não entendi o período. Responda com manhã, tarde ou noite.");

limparEspera();
return responder(mensagemNaoEntendi);

// 6 Processar Resposta BD: transforma o resultado do banco em mensagem.
// Saída 1 -> 7 resposta | Saída 2 -> 5.1 BD Gravação (segunda etapa, quando precisa gravar depois de consultar)
const linhas = Array.isArray(msg.payload) ? msg.payload : [];
msg.payload = msg.telegramContext || {};
const chatId = msg.payload.chatId;
const d = msg.dados || {};

const NOME_HORARIO = { manha: "manhã", tarde: "tarde", noite: "noite" };
const NOME_CARGA = { orgao: "órgão para transplante", remedio: "remédio", kit_emergencia: "kit de emergência",
    exame: "material de exame", encomenda: "encomenda" };

// Número com vírgula decimal (47.5 -> 47,5)
function km(n) {
    return String(n).replace(".", ",");
}
function responder(texto) {
    msg.payload.type = "message";
    msg.payload.content = texto;
    return [msg, null];
}
function gravar(acao, sql) {
    msg.acao = acao;
    msg.topic = sql;
    msg.telegramContext = msg.payload;
    return [null, msg];
}

// ---------- 1) Rastrear ----------
if (msg.acao === "rastrear") {
    if (linhas.length === 0) {
        return responder("Não encontrei a entrega " + d.codigo + ". Confira o código (ex.: SD1001).");
    }
    const e = linhas[0];
    const carga = NOME_CARGA[e.TP_Carga] || e.TP_Carga;
    if (e.ST_Status === "em_voo") {
        return responder("📦 Entrega " + e.CD_Rastreio + " (" + carga + " para " + e.NM_Destino + "): em voo monitorado " +
            "pelo drone " + e.CD_Drone + ". Previsão: " + e.NR_Previsao_Min + " minutos. A central acompanha bateria, posição, " +
            "temperatura e vibração da carga em tempo real.");
    }
    if (e.ST_Status === "entregue") {
        return responder("✅ Entrega " + e.CD_Rastreio + " (" + carga + " para " + e.NM_Destino + ") já foi entregue e o recebimento foi registrado.");
    }
    if (e.ST_Status === "reagendada") {
        return responder("🕒 Entrega " + e.CD_Rastreio + " (" + carga + " para " + e.NM_Destino + ") foi reagendada para o período da " +
            (NOME_HORARIO[e.DS_Periodo] || e.DS_Periodo) + ". Avisaremos quando o drone decolar.");
    }
    return responder("🕒 Entrega " + e.CD_Rastreio + " (" + carga + " para " + e.NM_Destino + ") está na fila com prioridade nível " +
        e.NR_Prioridade + ", aguardando decolagem no período da " + (NOME_HORARIO[e.DS_Periodo] || e.DS_Periodo) + ".");
}

// ---------- 2) Remédio gravado ----------
if (msg.acao === "remedio_registrado") {
    let t = "💊 Pedido de remédio registrado!\nCódigo: " + d.codigo + "\nBairro: " + d.bairro +
        "\nPeríodo: " + NOME_HORARIO[d.periodo] + "\nPrioridade: nível 3 (Saúde)";
    if (d.lembrouBairro) {
        t += "\n\nUsei o bairro que você já tinha informado: " + d.bairro + ".";
    }
    t += "\n\nPara acompanhar, pergunte \"onde está minha entrega?\".";
    return responder(t);
}

// ---------- 3) Transporte urgente: escolha do drone ----------
if (msg.acao === "escolher_drone") {
    if (linhas.length === 0) {
        // REGRA: se nenhum drone cobre a rota, o sistema avisa que é preciso outro transporte.
        const folga = d.prioridade === 1 ? " com 30% de folga" : "";
        const outro = d.prioridade === 1
            ? "A Central de Transplantes deve acionar helicóptero ou ambulância."
            : "Acione a Defesa Civil (199). Se houver risco de vida, ligue para o SAMU (192).";
        return responder("⚠️ Nenhum drone disponível agora tem bateria para ir e voltar de " + d.destino + folga + ". " + outro);
    }
    const dr = linhas[0];
    d.drone = dr.CD_Drone;
    d.bateria = dr.NR_Bateria_Pct;
    d.alcance = dr.alcance_km;
    d.distancia = dr.NR_Distancia_Km;
    d.previsao = Math.round(dr.NR_Distancia_Km) + 3;      // drone a ~60 km/h + 3 min de decolagem
    d.tomouComercial = (dr.ST_Status === "aguardando_comercial");
    msg.dados = d;

    // Grava tudo de uma vez (nó 5.1 em modo lote): a entrega nova, o drone em voo e,
    // se o drone estava reservado para uma entrega comercial, essa entrega é reagendada.
    let sql = "INSERT INTO tbl_entrega (CD_Rastreio, NR_Chat, NM_Destino, TP_Carga, NR_Prioridade, ST_Status, DS_Periodo, " +
        "CD_Drone, NR_Previsao_Min, DT_Pedido) VALUES ('" + d.codigo + "', '" + String(chatId).replace(/'/g, "''") + "', '" +
        d.destino + "', '" + d.carga + "', " + d.prioridade + ", 'em_voo', 'agora', '" + d.drone + "', " + d.previsao +
        ", datetime('now', 'localtime'));\n";
    if (d.tomouComercial) {
        sql += "UPDATE tbl_entrega SET ST_Status = 'reagendada', CD_Drone = NULL WHERE CD_Drone = '" + d.drone +
            "' AND ST_Status = 'aguardando' AND NR_Prioridade = 4;\n";
    }
    sql += "UPDATE tbl_drone SET ST_Status = 'em_voo' WHERE CD_Drone = '" + d.drone + "';";

    // Guarda o código na memória da conversa, para "onde está minha entrega?" funcionar depois.
    const memoria = flow.get("memoria_" + chatId) || {};
    memoria.ultimo_codigo = d.codigo;
    flow.set("memoria_" + chatId, memoria);

    return gravar("urgente_registrado", sql);
}

if (msg.acao === "urgente_registrado") {
    const nivel = d.prioridade === 1 ? "🫀 Pedido nível 1 (órgão)" : "🚨 Chamado nível 2 (emergência)";
    const regra = d.prioridade === 1
        ? "A rota de ida e volta (" + km(d.distancia * 2) + " km) mais 30% de folga cabe no alcance da bateria (" + km(d.alcance) + " km)."
        : "A rota de ida e volta (" + km(d.distancia * 2) + " km) cabe no alcance da bateria (" + km(d.alcance) + " km).";
    let t = nivel + " registrado.\nCódigo: " + d.codigo + "\nDestino: " + d.destino +
        "\nDrone: " + d.drone + " (bateria " + d.bateria + "%)\nPrevisão: " + d.previsao + " minutos\n\n" + regra;
    if (d.tomouComercial) {
        t += "\n\nEsse drone estava reservado para uma entrega comercial que ainda não tinha decolado: ela foi reagendada e o cliente será avisado.";
    }
    return responder(t);
}

// ---------- 4) Reagendar ----------
if (msg.acao === "conferir_reagendamento") {
    if (linhas.length === 0) {
        return responder("Não encontrei a entrega " + d.codigo + ". Confira o código (ex.: SD1002).");
    }
    const e = linhas[0];
    // REGRA: drone já em voo termina a entrega; não dá para reagendar.
    if (e.ST_Status === "em_voo") {
        return responder("O drone da entrega " + d.codigo + " já decolou. Entregas em voo são sempre concluídas, então não dá para reagendar.");
    }
    if (e.ST_Status === "entregue") {
        return responder("A entrega " + d.codigo + " já foi entregue.");
    }
    if (e.NR_Prioridade === 1) {
        return responder("Transporte de órgão não pode ser reagendado pelo chat. Fale com a Central de Transplantes.");
    }
    return gravar("reagendado",
        "UPDATE tbl_entrega SET DS_Periodo = '" + d.horario + "', ST_Status = 'reagendada' WHERE CD_Rastreio = '" + d.codigo + "'");
}

if (msg.acao === "reagendado") {
    return responder("🕒 Pronto! A entrega " + d.codigo + " foi reagendada para o período da " + NOME_HORARIO[d.horario] +
        ". Avisaremos quando o drone decolar.");
}

// ---------- 5) Ocorrência gravada ----------
if (msg.acao === "ocorrencia_registrada") {
    let t = "Sinto muito pelo transtorno. Sua ocorrência foi registrada" + (d.codigo ? " para a entrega " + d.codigo : "") +
        " e a central de operação vai analisar.";
    t += "\n\nSe você viu um drone caído ou com a luz de alerta piscando, não se aproxime: ele está programado para pousar " +
        "em uma zona de pouso seguro, e uma equipe vai resgatar a carga.";
    return responder(t);
}

return responder("Desculpe, algo deu errado ao consultar os dados. Tente de novo.");

// 7 Gera Texto e Rota TTS: entrega a resposta no canal certo.
// Saída 1 -> Telegram (texto) | Saída 2 -> áudio (TTS) no Telegram | Saída 3 -> resposta do Webchat
const p = msg.payload || {};
const chatId = p.chatId || (msg.telegramContext && msg.telegramContext.chatId) || msg.chatId;
const texto = p.content;
if (!chatId || !texto) return [null, null, null];

// ---------- Webchat: devolve o texto para a página (somente texto) ----------
if (msg.canal === "web") {
    msg.payload = { resposta: texto };
    msg.statusCode = 200;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    return [null, null, msg];
}

// ---------- Telegram ----------
// VARIÁVEL DE CONTEXTO: como esta pessoa quer receber as respostas ("responda em áudio" / "responda em texto").
// Quem mandou a pergunta por áudio também recebe em áudio.
const preferencia = flow.get("formato_" + chatId);
const formato = preferencia || (msg.veioDeAudio ? "audio" : "texto");

// O texto completo sempre vai (no áudio as respostas longas são resumidas).
const mensagens = [{ payload: { chatId: chatId, type: "message", content: texto } }];
if (formato === "texto") {
    return [mensagens, null, null];
}

// ---------- Formato "audio": limpa o texto para a voz ----------
let cleanText = texto
    .replace(/\bSD(\d)/g, "SD $1")                   // lê o código separado
    .replace(/\s*\(?ou \/(audio|texto)\)?/g, "")
    .replace(/[*_#`•]/g, "")
    .replace(/([✀-➿]|[-]|\uD83C[\uDC00-\uDFFF]|\uD83D[\uDC00-\uDFFF]|[☀-⛿]|\uD83E[\uDD10-\uDDFF])/g, "")
    .replace(/["'`()\[\]{}]/g, "")
    .replace(/\/(audio|texto|ajuda)/g, "")
    .replace(/\n+/g, ". ")
    .replace(/\s+/g, " ")
    .replace(/(\. )+/g, ". ")
    .replace(/:\./g, ":")
    .trim();

// A boas-vindas é longa: no áudio vai um resumo
if (cleanText.toLowerCase().includes("eu sou o assistente sadec")) {
    cleanText = "Olá! Eu sou o Assistente SADEC. Posso rastrear sua entrega, pedir seu remédio, solicitar transporte urgente, reagendar ou registrar um problema.";
}

// O gerador de voz aceita frases curtas: corta no fim da última frase que couber em 200 caracteres
if (cleanText.length > 200) {
    const trecho = cleanText.substring(0, 200);
    const fim = Math.max(trecho.lastIndexOf(". "), trecho.lastIndexOf("? "), trecho.lastIndexOf("! "));
    cleanText = fim > 40 ? trecho.substring(0, fim + 1) : trecho.substring(0, 197) + "...";
}
if (!cleanText) cleanText = "Pedido processado com sucesso.";

// Voz gerada pelo TTS do Google e enviada direto pela API do Telegram (sendAudio com o link do áudio)
const TELEGRAM_BOT_TOKEN = env.get("TELEGRAM_BOT_TOKEN");
const audioUrl = "https://translate.google.com/translate_tts?ie=UTF-8&q=" + encodeURIComponent(cleanText) + "&tl=pt-BR&client=tw-ob";
const msgVoz = {
    method: "GET",
    url: "https://api.telegram.org/bot" + TELEGRAM_BOT_TOKEN + "/sendAudio?chat_id=" + chatId + "&audio=" + encodeURIComponent(audioUrl)
};
return [mensagens, msgVoz, null];

// W2 Webchat: preparar entrada
// A página envia {sessao, texto}. Transformamos no mesmo formato de mensagem do Telegram,
// assim o resto do fluxo (nós 3 a 7) é o mesmo para os dois canais.
const corpo = msg.payload || {};
const sessao = String(corpo.sessao || "anonimo").replace(/[^a-zA-Z0-9]/g, "").substring(0, 20);

msg.canal = "web";
msg.chatId = "web-" + sessao;          // cada aba do navegador tem a própria memória
msg.payload = {
    chatId: msg.chatId,
    type: "message",
    content: String(corpo.texto || "").substring(0, 500)
};
return msg;

// Criar pedido: chama o núcleo comum e devolve JSON com status HTTP.
const api = global.get("sadecApi");
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
try {
    msg.payload = { ok: true, dados: api.criarPedido(msg.payload) };
    msg.statusCode = 201;
} catch (e) {
    msg.statusCode = e.status || 500;
    msg.payload = { ok: false, erro: e.status ? e.message : "Erro interno.", detalhes: e.detalhes || null };
    if (!e.status) node.error(e, msg);
}
return msg;

